# Find all hollow boxes in the grid
def find_all_hollow_boxes(grid):
    rows = len(grid)
    cols = len(grid[0])
    visited = set()
    boxes = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 6:
                continue
            if (r, c) in visited:
                continue

            ext_color = grid[r][c]
            border_cells = []
            for rr in range(rows):
                for cc in range(cols):
                    if grid[rr][cc] == ext_color:
                        border_cells.append((rr, cc))
                        visited.add((rr, cc))

            if len(border_cells) < 4:
                continue

            min_row = min(rr for rr, cc in border_cells)
            max_row = max(rr for rr, cc in border_cells)
            min_col = min(cc for rr, cc in border_cells)
            max_col = max(cc for rr, cc in border_cells)

            interior_cells = []
            for rr in range(min_row + 1, max_row):
                for cc in range(min_col + 1, max_col):
                    if grid[rr][cc] != ext_color:
                        interior_cells.append((rr, cc))

            if len(interior_cells) > 0:
                boxes.append({
                    'ext_color': ext_color,
                    'interior_cells': interior_cells
                })

    return boxes

